INSERT INTO clinica.raza (especie_id, nombre, descripcion)
VALUES 
-- ==========================================
-- ESPECIE CANINA (especie_id = 1) - 60 Razas
-- ==========================================
(1, 'Labrador Retriever', 'Biotipo mesomorfo. Alta casuística de displasia coxofemoral, miopatía centronuclear, rotura de ligamento cruzado craneal (RLCC) y obesidad de origen metabólico/endocrino.'),
(1, 'Golden Retriever', 'Predisposición genética a patologías oncológicas (hemangiosarcoma esplénico, linfoma multicéntrico, mastocitoma), así como atopia y displasia de codo.'),
(1, 'Pastor Alemán', 'Biotipo lupoide. Alta prevalencia de mielopatía degenerativa, insuficiencia pancreática exocrina (IPE), panosteítis y estenosis lumbosacra degenerativa.'),
(1, 'Bulldog Inglés', 'Braquicéfalo extremo. Casuística dominada por el síndrome respiratorio braquicefálico (BOAS), hipoplasia traqueal, distocia (frecuentemente requiere cesárea) y queratoconjuntivitis seca.'),
(1, 'Bulldog Francés', 'Condrodistrófico y braquicéfalo. Alta incidencia de enfermedad de disco intervertebral (Hansen tipo I), hemivértebras, BOAS y dermatitis de pliegues (intertrigo).'),
(1, 'Pug', 'Braquicéfalo. Predisposición a meningoencefalitis necrotizante (encefalitis del Pug), úlceras corneales indolentes crónicas y colapso laríngeo.'),
(1, 'Caniche Standard', 'Biotipo dolicocéfalo. Riesgo elevado de síndrome de dilatación-vólvulo gástrico (DVG), hipoadrenocorticismo (Addison) y adenitis sebácea granulomatosa.'),
(1, 'Caniche Toy', 'Predisposición anatómica a luxación rotuliana medial, colapso traqueal de grado variable y enfermedad periodontal severa precoz.'),
(1, 'Chihuahua', 'Raza miniatura. Frecuente retención de piezas dentales deciduas, hidrocefalia congénita (asociada a fontanela persistente) e hipoglucemia juvenil transitoria.'),
(1, 'Yorkshire Terrier', 'Alta incidencia de derivación portosistémica congénita (shunt), urolitiasis por uratos, luxación atlantoaxial y colapso traqueal primario.'),
(1, 'Boxer', 'Biotipo molosoide. Marcada predisposición a cardiomiopatía arritmogénica del ventrículo derecho, procesos neoplásicos cutáneos (mastocitoma) e hiperplasia gingival (épulis).'),
(1, 'Doberman Pinscher', 'Biotipo mesomorfo. Casuística significativa de cardiomiopatía dilatada idiopática, enfermedad de von Willebrand tipo I y espondilomielopatía cervical (síndrome de Wobbler).'),
(1, 'Rottweiler', 'Molosoide de talla grande. Alta susceptibilidad a parvovirosis canina severa, osteosarcoma apendicular y poliartritis inmunomediada.'),
(1, 'Schnauzer Miniatura', 'Predisposición metabólica a hiperlipidemia idiopática, pancreatitis aguda recurrente y formación de urolitos de oxalato de calcio y estruvita.'),
(1, 'Dachshund (Teckel)', 'Biotipo condrodistrófico severo. Tasa altísima de extrusión de disco intervertebral (IVDD Hansen Tipo I) con paresia/plejia asociada.'),
(1, 'Shih Tzu', 'Braquicéfalo con órbitas poco profundas. Alta incidencia de proptosis del globo ocular, entropión y queratopatía por exposición.'),
(1, 'Beagle', 'Sabueso de talla media. Prevalencia notable de epilepsia idiopática, hipotiroidismo primario, obesidad endógena y dolor cervical (meningitis-arteritis que responde a esteroides).'),
(1, 'Border Collie', 'Raza de pastoreo. Portadores frecuentes de la mutación del gen MDR1 (ABCB1) que altera la barrera hematoencefálica frente a macrocíclicos, y anomalía del ojo del collie (CEA).'),
(1, 'Pastor Australiano', 'Alta casuística de toxicidad por mutación MDR1, cataratas hereditarias y sordera neurosensorial asociada a la expresión homocigota del gen merle.'),
(1, 'Gran Danés', 'Raza gigante. Predisposición biomecánica y anatómica a dilatación-vólvulo gástrico (requiere gastropexia preventiva), cardiomiopatía dilatada y osteosarcoma.'),
(1, 'Mastín Napolitano', 'Molosoide pesado. Alteraciones oftalmológicas frecuentes (ectropión/entropión confluentes), miocardiopatías y pioderma crónico de pliegues.'),
(1, 'Dogo Argentino', 'Molosoide de capa blanca. Alta prevalencia de sordera neurosensorial congénita ligada al pigmento y susceptibilidad a demodicosis sistémica juvenil.'),
(1, 'Husky Siberiano', 'Biotipo spitz. Predispuesto a dermatosis con respuesta al zinc (por defecto de absorción intestinal), glaucoma primario de ángulo estrecho y cataratas.'),
(1, 'Malamute de Alaska', 'Biotipo spitz pesado. Susceptibilidad a polineuropatía idiopática hereditaria, enanismo (condrodisplasia) y displasia coxofemoral.'),
(1, 'San Bernardo', 'Raza gigante. Incidencia crítica de osteosarcoma, dilatación-vólvulo gástrico (DVG) y patologías articulares del desarrollo (osteocondrosis disecante).'),
(1, 'Boyero de Berna', 'Raza gigante. Predisposición oncológica altamente específica a histiocitosis maligna (sarcoma histiocítico), además de displasia de codo y mastocitomas.'),
(1, 'Cavalier King Charles Spaniel', 'Raza toy. Incidencia genéticamente fijada de enfermedad mixomatosa de la válvula mitral de aparición temprana y siringomielia (malformación tipo Chiari).'),
(1, 'Cocker Spaniel Inglés', 'Alta tasa de otitis externa crónica proliferativa (por estenosis del conducto), queratoconjuntivitis seca mediada por inmunidad y seborrea primaria.'),
(1, 'Springer Spaniel', 'Prevalencia hereditaria de deficiencia de fosfofructoquinasa (PFK) causando miopatía/hemólisis, y fucosidosis neurológica.'),
(1, 'Basset Hound', 'Condrodistrófico. Genética asociada a glaucoma primario por goniodisgenesia, malasseziasis dérmica crónica y enfermedad de disco intervertebral.'),
(1, 'Bull Terrier', 'Predisposición a acrodermatitis letal (autosómica recesiva), nefritis hereditaria que deriva en ERC precoz y sordera congénita unilateral/bilateral.'),
(1, 'Staffordshire Bull Terrier', 'Alta tasa de L-2-hidroxiglutaricoaciduria (enfermedad neurometabólica), cataratas hereditarias juveniles y dermatitis atópica.'),
(1, 'Pitbull Terrier Americano', 'Casuística traumatológica/ortopédica dominada por rotura de ligamento cruzado craneal. Dermatológicamente predispuestos a atopia y mastocitomas cutáneos.'),
(1, 'Boston Terrier', 'Braquicéfalo ligero. Alteraciones frecuentes incluyen luxación patelar medial, distrofia corneal endotelial y trastornos respiratorios obstructivos.'),
(1, 'Pomerania', 'Biotipo spitz miniatura. Predisposición al arresto del ciclo folicular (Alopecia X o "enfermedad de la piel negra"), colapso traqueal y luxación rotuliana.'),
(1, 'Bichón Frisé', 'Predisposición clínica a la formación de cálculos en el tracto urinario inferior (estruvita y oxalato), dermatitis alérgica severa y cataratas corticales.'),
(1, 'Maltés', 'Raza toy. Alta incidencia de derivación portosistémica congénita, enteropatía crónica con pérdida de proteínas y enfermedad periodontal fulminante.'),
(1, 'Puggle', 'Cruce híbrido (Pug x Beagle). Presenta comorbilidades respiratorias intermedias, predisposición a obesidad y otitis media heredada del biotipo pendular.'),
(1, 'Labradoodle', 'Híbrido en consolidación. Comparte patologías parentales: predisposición a enfermedad de Addison, displasia de cadera y atopia canina.'),
(1, 'Akita Inu', 'Biotipo spitz grande. Susceptibilidad inmunomediada al síndrome uveodermatológico (similar al Vogt-Koyanagi-Harada humano), adenitis sebácea e hipotiroidismo.'),
(1, 'Shiba Inu', 'Biotipo spitz medio. Predisposición a glaucoma primario, dermatitis atópica refractaria y trastornos conductuales obsesivo-compulsivos.'),
(1, 'Chow Chow', 'Biotipo spitz molosoide. Incidencia muy alta de entropión severo congénito, miotonía congénita y displasia de codo secundaria a incongruencia articular.'),
(1, 'Shar Pei', 'Predisposición hereditaria a la fiebre familiar del Shar Pei (amiloidosis reactiva sistémica renal), mucinosis cutánea hialina y entropión primario.'),
(1, 'Dálmata', 'Defecto genético en el metabolismo de las purinas, predisponiendo crónicamente a urolitiasis por uratos. Incidencia elevada de sordera neurosensorial congénita.'),
(1, 'Setter Irlandés', 'Raza deportiva. Portadores de la inmunodeficiencia de adhesión leucocitaria bovina (CLAD), atrofia progresiva de retina y epilepsia idiopática.'),
(1, 'Pointer Inglés', 'Raza de muestra. Predisposición a neuropatía sensorial, displasia coxofemoral y distrofias neuroaxonales.'),
(1, 'Braco Alemán de Pelo Corto', 'Raza deportiva polivalente. Susceptibilidad al síndrome de dilatación-vólvulo gástrico, estenosis aórtica subvalvular y melanoma cutáneo.'),
(1, 'Weimaraner', 'Predisposición inmunológica a polimiopatía inmunomediada juvenil, distrofia corneal, hernia umbilical y síndrome de dilatación-vólvulo gástrico.'),
(1, 'Vizsla', 'Alta casuística de epilepsia idiopática primaria, adenitis sebácea idiopática y polimiopatía de los músculos masticatorios.'),
(1, 'Galgo (Greyhound)', 'Biotipo lebrel. Fisiología cardiovascular atípica (hipertrofia ventricular fisiológica), predisposición a osteosarcoma y metabolismo hepático deficiente de barbitúricos y propofol.'),
(1, 'Lebrel Afgano', 'Predisposición a mielopatía necrosante (mielomalacia progresiva), quilotórax idiopático recurrente y cataratas corticales.'),
(1, 'Whippet', 'Lebrel ligero. Presencia del alelo del gen de la miostatina (bully whippet), hipersensibilidad anestésica debido a nula reserva de grasa perirrenal y subcutánea.'),
(1, 'Crestado Chino', 'Raza exótica. Alta prevalencia de hipodoncia/oligodoncia estructural ligada al gen de la carencia de pelo, luxación primaria del cristalino y comedones dérmicos.'),
(1, 'Xoloitzcuintle', 'Raza sin pelo originaria de México. Similar al Crestado Chino en su aplasia dental múltiple congénita y fragilidad del tegumento frente a radiación UV.'),
(1, 'Terranova', 'Raza gigante de agua. Incidencia clínicamente importante de estenosis subaórtica congénita, cistinuria (defecto de reabsorción tubular) y displasia coxofemoral.'),
(1, 'Leonberger', 'Raza gigante. Predisposición a polineuropatía hereditaria (LPN1 y LPN2), osteosarcoma de huesos largos y parálisis laríngea geriátrica.'),
(1, 'Samoyedo', 'Biotipo spitz nórdico. Incidencia alta de glomerulopatía hereditaria ligada al cromosoma X, diabetes mellitus dependiente de insulina y atrofia progresiva de retina.'),
(1, 'Keeshond', 'Biotipo spitz. Predisposición genética al hiperparatiroidismo primario (adenoma paratiroideo), tetralogía de Fallot y diabetes mellitus.'),
(1, 'Papillon', 'Raza toy spaniel. Susceptibilidad a distrofia neuroaxonal, luxación rotuliana medial, fontanela abierta persistente e hipoglucemia neonatal.'),
(1, 'Pinscher Miniatura', 'Raza miniatura. Riesgo documentado de mucopolisacaridosis tipo VI, necrosis avascular de la cabeza femoral (enfermedad de Legg-Calvé-Perthes) y luxación patelar.'),

-- ==========================================
-- ESPECIE FELINA (especie_id = 2) - 20 Razas
-- ==========================================
(2, 'Gato Doméstico de Pelo Corto (DSH)', 'Genética heterogénea poblacional. Representan la mayor casuística clínica: enfermedad del tracto urinario inferior felino (FLUTD), enfermedad renal crónica (ERC) y retrovirosis (VIF/ViLeF).'),
(2, 'Gato Doméstico de Pelo Largo (DLH)', 'Fenotipo de manto extenso. Gran predisposición a impactación gastrointestinal por tricobezoares, enteropatías crónicas y dermatofitosis.'),
(2, 'Persa', 'Braquicéfalo severo. Patologías hereditarias críticas: poliquistosis renal autosómica dominante (PKD1), secuestros corneales pigmentarios crónicos, epífora y cardiomiopatía hipertrófica.'),
(2, 'Siamés', 'Biotipo longilíneo. Predisposición genética al asma felino (bronquitis eosinofílica), amiloidosis reactiva (hepática/renal), estrabismo convergente congénito y trastornos de pica.'),
(2, 'Maine Coon', 'Felino de talla gigante. Alta incidencia de cardiomiopatía hipertrófica (mutación específica del gen MyBPC3), atrofia muscular espinal felina (SMA) y displasia coxofemoral grave.'),
(2, 'Ragdoll', 'Biotipo grande y linfático. Presentan una mutación homocigota propia para cardiomiopatía hipertrófica (CMH), mayor formación de urolitiasis de oxalato y susceptibilidad clínica a peritonitis infecciosa felina (PIF).'),
(2, 'Sphynx', 'Raza atriquia (sin pelo). Susceptibilidad sistémica a cardiomiopatía hipertrófica primaria, urticaria pigmentosa (mastocitosis cutánea maculopapular) y sobrecrecimiento crónico de Malassezia sp.'),
(2, 'Bengalí', 'Híbrido de gato leopardo asiático. Riesgo elevado de neuropatía distal precoz, deficiencia eritrocítica de piruvato quinasa (anemia hemolítica crónica) y atrofia progresiva de la retina.'),
(2, 'British Shorthair', 'Fenotipo cobby pesado. Fuerte asociación genética con enfermedad poliquística renal (PKD), hemofilia B (deficiencia del factor IX) y propensión clínica a obesidad endocrina.'),
(2, 'Scottish Fold', 'Portadores de la mutación dominante del gen Fd. Desarrollan osteocondrodisplasia generalizada (anomalías del cartílago epifisario), cursando con artritis degenerativa anquilosante y dolor crónico incapacitante.'),
(2, 'Abisinio', 'Alta incidencia hereditaria de amiloidosis renal familiar, deficiencia de piruvato quinasa y degeneración retiniana hereditaria temprana.'),
(2, 'Oriental de Pelo Corto', 'Relacionado fenotípicamente con el Siamés. Predispuesto a asma felina crónico, cardiomiopatía dilatada (inusual en felinos modernos) y amiloidosis hepática con hemorragia parenquimatosa espontánea.'),
(2, 'Azul Ruso', 'Raza robusta. Tendencia documentada a la obesidad geriátrica, urolitiasis por oxalato de calcio en vías bajas y moderada predisposición a diabetes mellitus tipo II.'),
(2, 'Birmano (Sagrado de Birmania)', 'Predisposición a dermoides corneales congénitos, hipocaliemia episódica familiar (polimiopatía con ventroflexión cervical) y alteraciones en el metabolismo hepático de fármacos.'),
(2, 'Bosque de Noruega', 'Felino rústico de talla grande. Predisposición a enfermedad por almacenamiento de glucógeno tipo IV (GSD IV) que produce degeneración neuromuscular y hepática, además de displasia de cadera.'),
(2, 'Exótico de Pelo Corto', 'Es fenotípicamente y genéticamente equivalente al Persa pero de pelo corto. Misma incidencia epidemiológica de PKD1 renal, distocia pélvica y síndrome respiratorio obstructivo felino.'),
(2, 'Cornish Rex', 'Fenotipo con mutación en el folículo piloso (hipotricosis). Clínicamente predispuestos a miopatía hipocalémica, dermatitis descamativa primaria y alopecia simétrica.'),
(2, 'Devon Rex', 'Mutación del gen KRT71. Predisposición neurológica a espasticidad hereditaria (distrofia muscular del Devon), coagulopatía dependiente de la síntesis de vitamina K y luxación patelar.'),
(2, 'Siberiano', 'Gato de talla grande. Aunque rústico, presenta una incidencia moderada de cardiomiopatía hipertrófica. Clínicamente relevante por generar estadísticamente menor carga salival de la glucoproteína alérgena Fel d 1.'),
(2, 'Bobtail Japonés', 'Portadores de una mutación autosómica dominante que trunca el desarrollo de las vértebras coccígeas. No suele asociarse a malformaciones neurológicas pélvicas severas como el gen Manx.'),

-- ==========================================
-- GRANDES ANIMALES Y EXÓTICOS (20 Razas)
-- ==========================================
-- Equinos (especie_id = 8)
(8, 'Pura Sangre de Carrera (SPC)', 'Equino deportivo hipercortisolémico por estrés. Alta prevalencia de hemorragia pulmonar inducida por el ejercicio (EIPH), osteocondritis disecante (OCD) articular y síndrome de úlcera gástrica equina (EGUS).'),
(8, 'Cuarto de Milla', 'Equino de trabajo/deporte rápido. Predisposición hereditaria severa a parálisis periódica hiperpotasémica (HYPP) y miopatía por almacenamiento de polisacáridos equina (PSSM tipo 1).'),
(8, 'Árabe', 'Raza ligera de resistencia. Portadores del gen de inmunodeficiencia combinada severa equina (SCID), abiotrofia cerebelosa progresiva y síndrome del potro blanco letal (aganglionosis ileocólica).'),
(8, 'Caballo Criollo', 'Raza rústica sudamericana, biotipo eumétrico. Alta resiliencia metabólica, pero con susceptibilidad a síndrome metabólico equino crónico y laminitis (infosura) ante dietas hipercalóricas.'),

-- Bovinos (especie_id = 9)
(9, 'Holstein-Friesian', 'Biotipo lechero hiperproductivo. Altamente susceptibles a patologías del periparto: cetosis por balance energético negativo, hipocalcemia, metritis puerperal aguda y desplazamiento izquierdo del abomaso.'),
(9, 'Jersey', 'Biotipo lechero de menor talla con alta tasa metabólica de recambio de calcio lácteo. Altísima prevalencia de paresia puerperal hipocalcémica (fiebre de la leche) y toxicosis acumulativa por cobre hepático.'),
(9, 'Aberdeen Angus', 'Biotipo carnicero. Raza muy adaptada y productiva, con menor tasa de distocia que razas continentales, pero susceptible a hipertermia bajo estrés térmico e intoxicación por festuca (Festucosis endofítica).'),
(9, 'Hereford', 'Biotipo carnicero (cara blanca). Carencia de pigmentación periocular que desencadena una prevalencia epidémica de carcinoma de células escamosas ocular y prolapso crónico vaginal/uterino en hembras pluríparas.'),

-- Porcinos (especie_id = 12)
(12, 'Landrace', 'Raza materna hiperprolífica de biotipo alargado. Genéticamente susceptibles al síndrome de estrés porcino (mutación RYR1), desencadenando hipertermia maligna aguda y carne pálida, blanda y exudativa (PSE).'),
(12, 'Yorkshire (Large White)', 'Raza paterna de conversión rápida y magra. En sistemas de confinamiento intensivo, presentan predisposición ortopédica a osteocondrosis generalizada y afecciones podales por estrés mecánico.'),

-- Ovinos (especie_id = 10)
(10, 'Merino', 'Raza lanera rústica. La excesiva formación de pliegues cutáneos (arrugas) predispone crónicamente al impacto por miasis cutánea (flystrike), especialmente en la región perineal y dermatitis por humedad.'),
(10, 'Hampshire Down', 'Raza carnicera precoz. Los machos bajo esquemas de suplementación intensa en corrales (feedlot) presentan alta susceptibilidad a la urolitiasis obstructiva uretral (cálculos de fosfato amónico magnésico).'),

-- Lagomorfos (especie_id = 3)
(3, 'Conejo Neozelandés Blanco', 'Raza estandarizada productiva y de laboratorio. Clínicamente presenta altísima incidencia de pododermatitis ulcerativa severa, estasis gastrointestinal (íleo paralítico) y síndrome respiratorio por Pasteurella multocida.'),
(3, 'Conejo Belier (Lop)', 'Anatomía auricular modificada con cartílago pendular obstructivo. Resulta en predisposición crónica a otitis media proliferativa, osteomielitis de la bulla timpánica y síndrome vestibular periférico.'),

-- Roedores (especie_id = 4)
(4, 'Cobayo Peruano (Cavia porcellus)', 'Fisiología oral hipsodonta severa con rápido sobrecrecimiento molar. Carencia absoluta de la enzima L-gulonolactona oxidasa, predisponiendo irreversiblemente a escorbuto (hipovitaminosis C).'),
(4, 'Hámster Sirio (Mesocricetus auratus)', 'Raza exótica de bolsillo. Casuística dominada por enteritis proliferativa infecciosa (ileítis por Lawsonia intracellularis) y amiloidosis renal generalizada en etapa geriátrica.'),

-- Aves (especie_id = 5)
(5, 'Loro Gris Africano (Psittacus erithacus)', 'Psitácida de alto desarrollo cognitivo. Vulnerabilidad etológica marcada al picaje de plumas psicogénico (automutilación), hipocalcemia severa por dietas deficientes y aspergillosis respiratoria.'),
(5, 'Cacatúa Ninfa (Nymphicus hollandicus)', 'Psitácida de compañía. Predisposición endocrina reproductiva a la retención de huevos (distocia aviar por agotamiento de calcio) y hepatopatía lipídica severa mediada por dietas de semillas oleaginosas.'),

-- Teleósteos (especie_id = 14)
(14, 'Pez Betta (Betta splendens)', 'Laberíntido ornamental. Requerimiento de respiración aérea complementaria. Muy susceptibles a podredumbre bacteriana de aletas (Aeromonas/Pseudomonas) e hidropesía osmótica por fallas en calidad del agua.'),
(14, 'Carpa Koi (Cyprinus rubrofuscus)', 'Ciprínido ornamental de estanques de alta longevidad. Estrecho monitoreo clínico frente al Koi Herpesvirus (KHV) y parasitosis por crustáceos ectópicos (Lernaea cyprinacea).');